const rc=rs.filter(x=>x.r.ts).sort((a,b)=>b.r.ts-a.r.ts),fd=t=>new Date(t).toLocaleString('id-ID',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
