const juzS=j=>{const a=J[j-1],b=j==30?114:(BEG.includes(j+1)?J[j]-1:J[j]),r=[];for(let n=a;n<=b;n++)r.push(n);return r};
const juzOf=n=>{let j=1;J.forEach((x,i)=>{if(x<=n)j=i+1});return(J[j-1]==n&&j>1&&!BEG.includes(j))?j-1:j};
const NOTE={mk:[`Qalqalah kurang jelas`,`Perlu memperbaiki makhraj huruf ح dan ه`,`Perlu membedakan huruf ث dan س`],tj:[`Perlu lebih memperhatikan panjang-pendek bacaan`,`Perlu memperbaiki hukum nun mati dan tanwin`,`Perlu memperhatikan waqaf dan ibtida'`]};
let R=null,saveT=null;const TAB={},pk=()=>S.per||'umum';
const getR=id=>{const r=(S.rapor||[]).find(x=>x.id==id+'_'+pk());let d={};try{d=JSON.parse(r.data)}catch(e){}return{hafalan:[],tajwid:{total:'',benar:'',materi:''},cat:{},...d}};
const pct=h=>h.ayat>0&&h.salah!==''&&h.salah!=null?Math.max(0,Math.round((h.ayat-h.salah)/h.ayat*1000)/10):null;
const HP=h=>{const p=pct(h);if(p==null)return['-',-1];let k=p>=90?3:p>=80?2:p>=70?1:0;if(h.ulang)k=Math.min(k,1);return[['مقبول','جيد','جيد جدا','ممتاز'][k],k]};
const ts=(r=R)=>{const t=+r.tajwid.total,b=+r.tajwid.benar;return t>0&&r.tajwid.benar!==''?Math.min(100,Math.round(b/t*100)):null};
const tcat=x=>x==null?['-',-1]:x>=81?['Sangat Baik',3]:x>=41?['Baik',2]:x>=11?['Cukup Baik',1]:['Perlu Bimbingan',0];
const comp=(r=R)=>{const H=r.hafalan,c=r.cat;return[['Hafalan dinilai',H.length>0&&H.every(h=>pct(h)!=null)],['Makharijul huruf',H.length>0&&H.every(h=>h.mk)],['Tajwid per surat',H.length>0&&H.every(h=>h.tj)],['Catatan tahfiz',!!c.tahfiz],['Catatan tajwid',!!c.tjn]]};
const pgR=r=>comp(r).filter(x=>x[1]).length*20,pc=h=>{const p=pct(h);return p==null?'':String(p).replace('.',',')+'%'};
V.nilai=()=>S.cur?rpage():`<h1 class="pt">Input Penilaian</h1><p class="sub">Periode ${perRange(S.per)} · Pilih santri untuk mulai menilai; perubahan tersimpan otomatis.</p><div class="card"><div class="fb"><input class="srch" placeholder="Cari santri…" value="${esc(S.q)}" oninput="S.q=this.value;drawNil()"><select onchange="S.fk=this.value;drawNil()"><option value="">Semua kelas</option>${kelasL().map(k=>`<option ${S.fk==k?'selected':''}>${esc(k)}</option>`).join('')}</select><div class="seg">${['Semua','Belum','Proses','Selesai'].map(x=>`<b class="${S.nst==x?'on':''}" onclick="S.nst='${x}';render()">${x}</b>`).join('')}</div></div><div id="nl"></div></div>`;
function drawNil(){const l=flt().map(s=>{const r=getR(s.id);return{s,p:pgR(r),n:r.hafalan.length}}).filter(x=>S.nst=='Semua'||(S.nst=='Belum'?x.p==0:S.nst=='Proses'?x.p>0&&x.p<100:x.p==100));
$('#nl').innerHTML=`<div class="cg">${l.map(({s,p,n})=>{const t=p==0?['Belum mulai','na']:p<100?['Dalam proses','y']:['Selesai','g'];return`<div class="kc" onclick="openR('${s.id}')">${ring(p)}<div><b>${esc(s.nama)}</b><small>${esc(s.kelas)} · ${n} surat</small><span class="st ${t[1]}">${t[0]}</span></div><i>›</i></div>`}).join('')||'<p class="mut">Tidak ada santri</p>'}</div>`}
function openR(id){S.view='nilai';S.cur=id;S.tab=S.tab||'h';R=getR(id);render()}
async function flush(){if(saveT)await doSave()}
async function back(){await flush();S.cur=null;render()}
async function goR(i){const s=S.santri[i];if(!s)return;await flush();openR(s.id)}
async function prev(){await flush();rapor(S.cur)}
function rpage(){const s=S.santri.find(x=>x.id==S.cur),i=S.santri.indexOf(s);
return`<div class="card rh"><div class="rt"><button class="ib" onclick="back()">‹</button><div class="av big">${ini(s.nama)}</div><div class="ri"><h2>${esc(s.nama)}</h2><span class="mut">${esc(s.kelas)} · NIS ${esc(s.nis)} · Periode ${perRange(S.per)}</span></div><div class="rn"><button class="btn ghost sm" onclick="goR(${i-1})">‹ Sebelumnya</button><select onchange="goR(S.santri.findIndex(x=>x.id==this.value))">${S.santri.map(x=>`<option value="${x.id}" ${x.id==S.cur?'selected':''}>${esc(x.nama)}</option>`).join('')}</select><button class="btn ghost sm" onclick="goR(${i+1})">Berikutnya ›</button></div><div id="rring">${ring(pgR(R))}</div></div><div class="rs"><button class="btn ghost sm" onclick="prev()">👁 Pratinjau rapor</button><span id="svd" class="ok">✓ Tersimpan</span></div></div><div class="rg2"><div><div class="seg tabs">${[['h','Hafalan'],['t','Tajwid'],['c','Catatan']].map(x=>`<b class="${S.tab==x[0]?'on':''}" onclick="S.tab='${x[0]}';render()">${x[1]}${x[0]=='h'?`<em>${R.hafalan.length}</em>`:''}</b>`).join('')}</div><div id="rm">${TAB[S.tab]()}</div></div><aside id="asd">${aside()}</aside></div>`}
function aside(){const cs=comp(),H=R.hafalan,c=R.cat;return`<div class="card"><h3>Kelengkapan rapor</h3>${cs.map(x=>`<p class="cl"><i class="${x[1]?'ok':''}"></i>${x[0]}</p>`).join('')}<div class="pb"><u style="width:${pgR(R)}%"></u></div></div><div class="card"><h3>Pratinjau ringkas</h3><div class="pv"><b>PENILAIAN SUMATIF AKHIR SEMESTER</b><table><tr><th>No</th><th>Surat</th><th>Hafalan</th></tr>${H.map((h,i)=>`<tr><td>${i+1}</td><td>${SUR[h.sur-1]}</td><td><b>${HP(h)[0]}</b><br><small>${pc(h)}</small></td></tr>`).join('')}</table>${c.tahfiz?`<p><b>Catatan Tahfiz:</b> ${esc(c.tahfiz)}</p>`:''}${c.tjn?`<p><b>Catatan Tajwid:</b> ${esc(c.tjn)}</p>`:''}</div></div>`}
const upd=()=>{$('#asd').innerHTML=aside();$('#rring').innerHTML=ring(pgR(R));const e=$('#svd');e.textContent='Menyimpan…';e.className='mut';clearTimeout(saveT);saveT=setTimeout(doSave,1200)};
const rr=()=>{$('#rm').innerHTML=TAB[S.tab]();upd()};
async function doSave(){if(!R||!S.cur)return;clearTimeout(saveT);saveT=null;R.ts=Date.now();R.by=S.user.nama;const id=S.cur,k=pk(),H=R.hafalan,t=S.per?S.per+'-01':today(),mv={'Sangat baik':90,'Baik':75,'Cukup baik':55},A=a=>a.length?avg(a):null;
const nil=(kat,v)=>v==null?null:{sheet:'Nilai',obj:{id:`${id}_${k}_${kat}`,tanggal:t,santriId:id,kategori:kat,nilai:Math.round(v),catatan:'',guru:S.user.nama}};
const items=[{sheet:'Rapor',obj:{id:id+'_'+k,santriId:id,periode:k,data:JSON.stringify(R)}},nil('Hafalan',A(H.map(pct).filter(x=>x!=null))),nil('Makharijul Huruf',A(H.map(h=>mv[h.mk]).filter(Boolean))),nil('Tajwid',ts())].filter(Boolean);
try{await api('saveMany',{items});await load();const e=$('#svd');if(e&&!saveT){e.textContent='✓ Tersimpan';e.className='ok'}}catch(x){toast(x.message,1)}}
/* hafalan */
const scx=h=>`<b>${pc(h)||'-'}</b><span class="hp hp${HP(h)[1]}">${HP(h)[0]}</span>`;
const chips=(i,f,v,n)=>`<div><label>${f=='mk'?'Makharijul huruf':'Tajwid'}</label><div class="chips">${['Sangat baik','Baik','Cukup baik'].map(x=>`<span class="chip ${v==x?'on':''}" onclick="setC(${i},'${f}','${x}')">${x}</span>`).join('')}</div><select onchange="addN(${i},'${f}',this.value);this.selectedIndex=0"><option>+ Catatan…</option>${NOTE[f].map(x=>`<option>${x}</option>`).join('')}</select><textarea rows="2" oninput="hs(${i},'${f}n',this.value)">${esc(n)}</textarea></div>`;
const hcard=(h,i)=>`<div class="card hi"><div class="hh"><span class="no">${i+1}</span><div><b>${SUR[h.sur-1]}</b><small>Juz ${h.juz}${h.from>1||h.to<AY[h.sur-1]?` · ayat ${h.from}–${h.to}`:''}</small></div></div><div class="hr"><label>Jumlah ayat<input type="number" min="1" value="${h.ayat}" oninput="hs(${i},'ayat',this.value)"></label><label>Ayat salah<input type="number" min="0" value="${h.salah}" oninput="hs(${i},'salah',this.value)"></label><label class="ck"><input type="checkbox" ${h.ulang?'checked':''} onchange="hs(${i},'ulang',this.checked,1)">Mengulang</label><div class="sc" id="sc${i}">${scx(h)}</div><div class="mv"><button onclick="moveH(${i},-1)">↑</button><button onclick="moveH(${i},1)">↓</button><button class="x" onclick="delH(${i})">✕</button></div></div><div class="g2c">${chips(i,'mk',h.mk,h.mkn)}${chips(i,'tj',h.tj,h.tjn)}</div></div>`;
TAB.h=()=>{const j=S.juz||+S.set.juzAwal||30;return`<div class="pick"><label>Juz<select onchange="S.juz=+this.value;rr()">${[...Array(30)].map((_,k)=>`<option ${k+1==j?'selected':''}>${k+1}</option>`).join('')}</select></label><label>Surat<select id="f_sur">${juzS(j).map(n=>`<option value="${n}">${SUR[n-1]} (${AY[n-1]} ayat)</option>`).join('')}</select></label><button class="btn" onclick="addS(+$('#f_sur').value,${j});rr()">+ Tambah</button><button class="btn ghost" onclick="juzS(${j}).forEach(n=>addS(n,${j}));rr()">Semua surat juz ini</button><button class="btn ghost" onclick="rangeForm()">✎ Surat/rentang lain</button></div><p class="mut">Persentase = (jumlah ayat − ayat salah) ÷ jumlah ayat × 100. Kosongkan "Ayat salah" bila surat belum diuji.</p><div class="qk"><button class="btn ghost sm" onclick="fillQ('mk')">Isi makharij kosong: "sangat baik"</button><button class="btn ghost sm" onclick="fillQ('tj')">Isi tajwid kosong: "sangat baik"</button></div>${R.hafalan.map(hcard).join('')||'<div class="card mut">Belum ada surat. Pilih juz dan surat, lalu klik Tambah.</div>'}`};
function addS(n,j,f,t){f=f||1;t=t||AY[n-1];R.hafalan.push({id:uid(),sur:n,juz:j||juzOf(n),from:f,to:t,ayat:t-f+1,salah:'',ulang:false,mk:'',mkn:'',tj:'',tjn:''})}
function hs(i,k,v,re){const h=R.hafalan[i];h[k]=k=='ayat'?(+v||0):k=='salah'?(v===''?'':+v):v;if(re)return rr();const e=$('#sc'+i);if(e&&(k=='ayat'||k=='salah'))e.innerHTML=scx(h);upd()}
const lbl={mk:'makharijul huruf',tj:'tajwid'};
const auto=(f,n)=>!n||/^Alhamdulillah, (makharijul huruf|tajwid) Ananda [a-z ]+\.$/.test(n);
function setC(i,f,x){const h=R.hafalan[i];h[f]=x;if(auto(f,h[f+'n']))h[f+'n']=`Alhamdulillah, ${lbl[f]} Ananda ${x.toLowerCase()}.`;rr()}
function addN(i,f,v){if(!v||v.startsWith('+'))return;const h=R.hafalan[i];h[f+'n']=(h[f+'n']||'')+(h[f+'n']?'\n':'')+v+'.';rr()}
function fillQ(f){R.hafalan.forEach(h=>{if(!h[f]){h[f]='Sangat baik';h[f+'n']=`Alhamdulillah, ${lbl[f]} Ananda sangat baik.`}});rr()}
function moveH(i,d){const a=R.hafalan,j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];rr()}
function delH(i){R.hafalan.splice(i,1);rr()}
function rangeForm(){modal(`<h3>Surat / rentang lain</h3><div class="fg"><label class="full">Surat<select id="f_rs" onchange="$('#f_rf').value=1;$('#f_rt').value=AY[this.value-1]">${SUR.map((x,i)=>`<option value="${i+1}">${i+1}. ${x} (${AY[i]} ayat)</option>`).join('')}</select></label>${inp('rf','Dari ayat',1,'number')}${inp('rt','Sampai ayat',7,'number')}</div><div class="acts"><button class="btn ghost" onclick="closeM()">Batal</button><button class="btn" onclick="addRange()">Tambah</button></div>`)}
function addRange(){const n=+val('rs'),f=+val('rf'),t=+val('rt');if(!(f>=1&&f<=t&&t<=AY[n-1]))return toast('Rentang ayat tidak valid',1);addS(n,0,f,t);closeM();rr()}
/* tajwid */
const tres=()=>{const x=ts(),c=tcat(x);return`<div class="bn">${x??'-'}</div><div><span class="hp hp${c[1]}">${c[0]}</span><p class="mut" style="margin-top:6px">${x==null?'Isi total hukum dan jumlah benar.':`Persentase ${x}% kemampuan penerapan hukum tajwid.`}</p></div>`};
const ht=(k,v)=>{R.tajwid[k]=v;$('#tres').innerHTML=tres();upd()};
TAB.t=()=>{const t=R.tajwid;return`<div class="card"><h3>Hasil ujian tajwid</h3><p class="mut">Skor = jumlah benar ÷ total hukum × 100 (dibulatkan).</p><div class="fg3"><label>Total hukum tajwid yang dinilai<input type="number" min="0" value="${esc(t.total)}" oninput="ht('total',this.value)"></label><label>Jumlah benar<input type="number" min="0" value="${esc(t.benar)}" oninput="ht('benar',this.value)"></label><label>Materi tajwid yang dipelajari<input value="${esc(t.materi)}" oninput="ht('materi',this.value)"></label></div><div class="tres" id="tres">${tres()}</div></div><div class="card"><h3>Kriteria deskripsi hasil penilaian tajwid</h3>${[['Sangat Baik','81%–100%',3],['Baik','41%–80%',2],['Cukup Baik','11%–40%',1],['Perlu Bimbingan','0%–10%',0]].map(x=>`<div class="cr"><span class="hp hp${x[2]}">${x[0]}</span>${x[1]} kemampuan penerapan hukum tajwid</div>`).join('')}</div>`};
/* catatan */
const hc2=(k,v)=>{R.cat[k]=v;upd()},ci=(k,l,c='')=>`<label class="${c}">${l}<input value="${esc(R.cat[k])}" oninput="hc2('${k}',this.value)"></label>`;
TAB.c=()=>{const c=R.cat;return`<div class="card"><div class="fg">${ci('guru','Guru halaqah (tampil di rapor)')}${ci('panggil','Nama panggilan dalam narasi')}</div></div><div class="card"><h3>Catatan Halaqah Tahfizh</h3><p class="mut">Isi komentar, buat draf, lalu periksa dan sunting sebelum dicetak.</p><div class="fg">${ci('adab','Komentar adab')}${ci('tasmi',"Tasmi' (opsional)")}${ci('kom','Komentar hafalan / tajwid / makharijul huruf','full')}</div><p><button class="btn ghost sm" style="margin:14px 0" onclick="draf('tahfiz')">✨ Buat draf narasi tahfiz</button></p><textarea id="f_tahfiz" rows="6" oninput="hc2('tahfiz',this.value)">${esc(c.tahfiz)}</textarea></div><div class="card"><h3>Catatan Halaqah Tajwid</h3><p class="mut">Kategori hasil ujian tajwid diambil otomatis dari tab Tajwid.</p><div class="fg">${ci('adab2','Komentar adab')}${ci('perbaikan','Catatan perbaikan')}</div><p><button class="btn ghost sm" style="margin:14px 0" onclick="draf('tjn')">✨ Buat draf narasi tajwid</button></p><textarea id="f_tjn" rows="6" oninput="hc2('tjn',this.value)">${esc(c.tjn)}</textarea></div>`};
function draf(t){const s=S.santri.find(x=>x.id==S.cur),c=R.cat,nm=c.panggil||s.nama.split(' ')[0];let x;
if(t=='tahfiz'){const ps=R.hafalan.map(pct).filter(v=>v!=null),a=ps.length?avg(ps):null,lv=a==null?'baik':a>=85?'sangat baik':a>=70?'baik':'cukup baik';x=`Alhamdulillah, Ananda ${nm} ${c.adab||'memiliki adab yang baik dan selalu bersemangat selama halaqah'}. Ananda memiliki hafalan yang ${lv}${c.kom?' dan '+c.kom:' dan mampu menerapkan perbaikan yang disampaikan oleh guru'}. ${c.tasmi?c.tasmi+'. ':''}Semoga semangat Ananda semakin bertambah untuk menambah hafalan baru dan memuraja'ah hafalan lamanya sesering mungkin agar hafalannya menjadi kuat. Barakallahu fik, ${s.gender=='Perempuan'?'Shalihah':'Shalih'}.`}
else x=`Alhamdulillah, Ananda ${nm} ${c.adab2||'memiliki adab yang baik selama halaqah tajwid'}. Ananda telah mempelajari ${R.tajwid.materi||'makharijul huruf dan sifat huruf'} serta mempraktikkannya dalam membaca potongan ayat Al-Qur'an dengan ${ts()==null?'baik':tcat(ts())[0].toLowerCase()}. ${c.perbaikan?c.perbaikan+'. ':''}Semoga Allah mudahkan Ananda untuk terus memperbaiki bacaan Al-Qur'an sesuai kaidah tajwid. Barakallahu fik.`;
R.cat[t]=x;$('#f_'+t).value=x;upd()}
function lap(){const m=S.per,k=S.lk;return S.santri.filter(s=>!k||s.kelas==k).map(s=>{const ns=nl(s.id).filter(n=>!m||n.tanggal.startsWith(m));return{s,per:cats().map(c=>avg(ns.filter(n=>n.kategori==c).map(n=>n.nilai))),v:avg(ns.map(n=>n.nilai))}}).sort((a,b)=>(b.v??-1)-(a.v??-1))}
V.laporan=()=>{const r=lap();return`<div class="top"><h2>Laporan</h2><div class="row noprint" style="min-width:min(100%,520px)"><select onchange="S.lk=this.value;render()"><option value="">Semua kelas</option>${kelasL().map(k=>`<option ${S.lk==k?'selected':''}>${esc(k)}</option>`).join('')}</select><button class="btn ghost" style="flex:0" onclick="csv()">CSV</button><button class="btn" style="flex:0" onclick="print()">Cetak</button></div></div><div class="card"><h4>Peringkat rata-rata nilai ${S.per?'· '+S.per:''}</h4>${bars(r.filter(x=>x.v!=null).map(x=>({l:x.s.nama,v:x.v})))}</div><div class="card" style="margin-top:16px"><table><tr><th>#</th><th>Nama</th><th>Kelas</th>${cats().map(c=>`<th>${esc(c)}</th>`).join('')}<th>Rata²</th><th>Predikat</th></tr>${r.map((x,i)=>`<tr class="click" onclick="rapor('${x.s.id}')"><td>${i+1}</td><td><b>${esc(x.s.nama)}</b></td><td>${esc(x.s.kelas)}</td>${x.per.map(p=>`<td>${f1(p)}</td>`).join('')}<td><span class="tag ${cls(x.v)}">${f1(x.v)}</span></td><td>${pred(x.v)}</td></tr>`).join('')}</table></div>`};
function csv(){const h=['Nama','Kelas',...cats(),'Rata-rata','Predikat'],r=lap().map(x=>[x.s.nama,x.s.kelas,...x.per.map(f1),f1(x.v),pred(x.v)]),t=[h,...r].map(a=>a.map(c=>`"${String(c).replace(/"/g,'""')}"`).join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([t],{type:'text/csv'}));a.download='laporan-tpq.csv';a.click()}
const usersTab=()=>`<div class="card"><div class="ch"><h3>Akun pengguna</h3><button class="btn" onclick="userForm()">+ Pengguna</button></div><div class="tw"><table class="tbl"><tr><th>Nama</th><th>Username</th><th>Peran</th><th>Santri terhubung</th><th></th></tr>${S.users.map(u=>`<tr><td>${esc(u.nama)}</td><td>${esc(u.username)}</td><td><span class="tag">${u.role}</span></td><td class="mut">${String(u.santriId||'').split(',').filter(Boolean).map(i=>(S.santri.find(s=>s.id==i)||{}).nama).join(', ')||'-'}</td><td><button class="btn sm ghost" onclick="userForm('${u.id}')">Edit</button> ${u.id!=S.user.id?`<button class="btn sm red" onclick="rm('Users','${u.id}')">Hapus</button>`:''}</td></tr>`).join('')}</table></div></div>`;
function userForm(id){const u=S.users.find(x=>x.id==id)||{},ids=String(u.santriId||'').split(',');modal(`<h3>${id?'Edit':'Tambah'} Pengguna</h3><div class="fg">${inp('nama','Nama',u.nama)}${inp('un','Username',u.username)}${inp('pw','Password'+(id?' (kosongkan jika tidak diubah)':''),'','password')}<label>Peran<select id="f_role">${['admin','guru','wali'].map(r=>`<option ${u.role==r?'selected':''}>${r}</option>`).join('')}</select></label><label class="full">Santri yang dilihat wali (tahan Ctrl/Cmd untuk pilih banyak)<select id="f_sids" multiple size="5">${S.santri.map(s=>`<option value="${s.id}" ${ids.includes(s.id)?'selected':''}>${esc(s.nama)}</option>`).join('')}</select></label></div><div class="acts"><button class="btn ghost" onclick="closeM()">Batal</button><button class="btn" onclick="saveUser('${id||''}')">Simpan</button></div>`)}
function saveUser(id){if(!val('nama')||!val('un')||(!id&&!val('pw')))return toast('Lengkapi nama, username, password',1);const o={id:id||undefined,nama:val('nama'),username:val('un'),role:val('role'),santriId:[...$('#f_sids').selectedOptions].map(o=>o.value).join(',')};if(val('pw'))o.password=val('pw');sv('Users',o,'Pengguna tersimpan')}
/* ===== PENGATURAN ===== */
IC.msg=IC.wa;IC.db='<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12c0 1.7 3.6 3 8 3s8-1.3 8-3"/>';IC.key='<circle cx="8" cy="15" r="4"/><path d="M11 12l9-9M16 7l3 3"/>';
const STAB=[['sekolah','Sekolah & Logo','dash'],['kop','Kop Surat','laporan'],['periode','Periode','cal'],['kelas','Kelas & Guru','layers'],['akun','Akun','key'],['surat','Katalog Surat','jurnal'],['wa','WhatsApp','msg'],['data','Backup & Data','db']];
const SP={};
const lines=v=>String(v||'').split('\n').map(x=>x.trim()).filter(Boolean);
const guruL=()=>[...new Set([...lines(S.set.guruList),...S.santri.map(s=>String(s.guru||'').trim()).filter(Boolean)])];
const fin=(k,l,v,c='',t='text',ph='')=>`<label class="${c}">${l}<input id="f_${k}" type="${t}" value="${esc(v)}" placeholder="${esc(ph)}"></label>`;
V.setting=()=>{S.stab=S.stab||'sekolah';return`<h1 class="pt">Pengaturan</h1><p class="sub">Identitas sekolah, periode rapor, kelas &amp; guru, akun pengguna, katalog surat, serta backup data.</p><div class="stabs">${STAB.map(([k,l,i])=>`<button class="${S.stab==k?'on':''}" onclick="stab('${k}')">${ic(i,17)}${l}${k=='akun'?`<em>${S.users.length}</em>`:''}</button>`).join('')}</div>${SP[S.stab]()}`};
function stab(k){const x=$('.stabs').scrollLeft;S.stab=k;render();$('.stabs').scrollLeft=x}
async function putSet(map,msg){try{await api('saveSettings',{map});await load();render();toast(msg||'Pengaturan tersimpan');return true}catch(e){toast(e.message,1);return false}}
/* Sekolah & Logo */
SP.sekolah=()=>`<div class="sg"><div class="card"><h3>Identitas sekolah</h3><p class="sub2">Dipakai di menu, halaman masuk, dan rapor.</p><div class="fg">${fin('namaTpq','Nama TPQ',S.set.namaTpq,'full')}${fin('ketua','Nama ketua / kepala TPQ',S.set.ketua,'','text','tampil di tanda tangan rapor')}${fin('jabatan','Sebutan jabatan',S.set.jabatan||'Kepala TPQ')}${fin('kkm','KKM (nilai minimal tuntas)',S.set.kkm,'','number')}${fin('kategori','Kategori penilaian (pisahkan dengan koma)',S.set.kategori,'full')}</div><div class="acts"><button class="btn" onclick="saveSekolah()">Simpan</button></div></div>
<div class="card"><h3>Logo</h3><p class="sub2">PNG atau JPG. Ukurannya otomatis diperkecil.</p><div class="logobox">${S.set.logo?`<img src="${esc(S.set.logo)}" alt="Logo">`:'<div class="lm">ح</div>'}</div><div class="acts">${S.set.logo?`<button class="btn red" onclick="putSet({logo:''},'Logo dihapus')">Hapus logo</button>`:''}<button class="btn ghost" onclick="$('#lgf').click()">Unggah logo</button><input id="lgf" type="file" accept="image/png,image/jpeg,image/webp" hidden onchange="upLogo(this)"></div></div></div>`;
function saveSekolah(){if(!val('namaTpq'))return toast('Nama TPQ wajib diisi',1);const m={};['namaTpq','ketua','jabatan','kkm','kategori'].forEach(k=>m[k]=val(k));putSet(m)}
function upLogo(el){const f=el.files[0];if(!f)return;const u=URL.createObjectURL(f),im=new Image();
im.onerror=()=>toast('Berkas gambar tidak bisa dibaca',1);
im.onload=()=>{let max=240,d;do{const k=Math.min(1,max/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*k));c.height=Math.max(1,Math.round(im.height*k));c.getContext('2d').drawImage(im,0,0,c.width,c.height);d=c.toDataURL('image/png');max=Math.round(max*.8)}while(d.length>45000&&max>40);URL.revokeObjectURL(u);putSet({logo:d},'Logo tersimpan')};im.src=u}
/* Kop Surat */
const kopVal=()=>({...S.set,kopYayasan:val('kopYayasan'),kopAlamat:val('kopAlamat'),kopKontak:val('kopKontak'),kopJudul:val('kopJudul'),kopLogo:$('#f_kopLogo').checked?'1':'0'});
function kopPrev(){$('#kopp').innerHTML=kopHtml(kopVal())}
