function saveKop(){const o=kopVal(),m={};['kopYayasan','kopAlamat','kopKontak','kopJudul','kopLogo'].forEach(k=>m[k]=o[k]);putSet(m)}
/* Periode */
SP.periode=()=>`<div class="card"><h3>Periode rapor</h3><p class="sub2">Periode aktif otomatis terpilih saat pengguna masuk.</p><div class="fg"><label>Periode aktif<select id="f_periodeAktif"><option value="">Otomatis (sesuai bulan berjalan)</option>${perOptsSet()}</select></label>${fin('tahunPelajaran','Tahun pelajaran',S.set.tahunPelajaran,'','text','kosong = otomatis')}${fin('kota','Kota (di atas tanda tangan)',S.set.kota)}${fin('tglRapor','Tanggal rapor',String(S.set.tglRapor||'').slice(0,10),'','date')}</div><div class="acts"><button class="btn" onclick="savePeriode()">Simpan</button></div></div>`;
function perOptsSet(){const cur=String(S.set.periodeAktif||'').slice(0,7),y=new Date().getFullYear(),a=[];for(let i=y+1;i>=y-2;i--)['10','07','04','01'].forEach(m=>a.push(i+'-'+m));if(cur&&!a.includes(cur))a.push(cur);return a.sort().reverse().map(k=>`<option value="${k}" ${k==cur?'selected':''}>${perLabel(k)}</option>`).join('')}
async function savePeriode(){const m={};['periodeAktif','tahunPelajaran','kota','tglRapor'].forEach(k=>m[k]=val(k));if(await putSet(m)){S.per=m.periodeAktif||qStart(ltoday().slice(0,7));render()}}
/* Kelas & Guru */
const nS=(k,v)=>S.santri.filter(s=>String(s[k]||'').trim()==v).length;
const listCard=(t,sb,arr,k,fn,ph)=>`<div class="card"><h3>${t}</h3><p class="sub2">${sb}</p>${arr.map((x,i)=>`<div class="li"><span><b>${esc(x)}</b><br><small>${nS(k,x)} santri</small></span><button class="ib2" aria-label="Ubah" onclick="${fn}Edit(${i})">✎</button><button class="ib2 x" aria-label="Hapus" onclick="${fn}Del(${i})">🗑</button></div>`).join('')||'<p class="mut">Belum ada.</p>'}<form class="add" onsubmit="${fn}Add();return false"><input id="f_${fn}" placeholder="${ph}"><button class="btn">Tambah</button></form></div>`;
SP.kelas=()=>`<div class="grid g2">${listCard('Kelas / halaqah','Mengubah nama kelas ikut memperbarui data santrinya.',kelasL(),'kelas','kls','Nama kelas baru')}${listCard('Guru halaqah','Muncul sebagai pilihan saat mengisi data santri.',guruL(),'guru','gr','Nama guru baru')}</div>`;
const okKls=n=>{if(!n)return false;if(n.includes(',')){toast('Nama kelas tidak boleh memakai koma',1);return false}if(kelasL().includes(n)){toast('Kelas sudah ada',1);return false}return true};
function klsAdd(){const n=val('kls');if(okKls(n))putSet({kelas:[...kelasL(),n].join(',')},'Kelas ditambahkan')}
async function moveSantri(k,from,to){const items=S.santri.filter(s=>String(s[k]||'').trim()==from).map(s=>({sheet:'Santri',obj:{...s,[k]:to}}));if(items.length)await api('saveMany',{items})}
async function klsEdit(i){const a=kelasL(),o=a[i],n=(prompt('Ubah nama kelas',o)||'').trim();if(n==o||!okKls(n))return;a[i]=n;try{await moveSantri('kelas',o,n);await putSet({kelas:a.join(',')},'Kelas diperbarui')}catch(e){toast(e.message,1)}}
function klsDel(i){const a=kelasL(),o=a[i];if(nS('kelas',o))return toast('Kelas masih berisi santri. Pindahkan santrinya dulu.',1);if(!confirm('Hapus kelas '+o+'?'))return;a.splice(i,1);putSet({kelas:a.join(',')},'Kelas dihapus')}
function grAdd(){const n=val('gr');if(!n)return;if(guruL().includes(n))return toast('Guru sudah ada',1);putSet({guruList:[...guruL(),n].join('\n')},'Guru ditambahkan')}
async function grEdit(i){const a=guruL(),o=a[i],n=(prompt('Ubah nama guru',o)||'').trim();if(!n||n==o)return;a[i]=n;try{await moveSantri('guru',o,n);await putSet({guruList:[...new Set(a)].join('\n')},'Nama guru diperbarui')}catch(e){toast(e.message,1)}}
function grDel(i){const a=guruL(),o=a[i];if(nS('guru',o))return toast('Guru masih punya santri. Ganti guru santrinya dulu.',1);if(!confirm('Hapus '+o+' dari daftar?'))return;a.splice(i,1);putSet({guruList:a.join('\n')},'Guru dihapus')}
/* Akun */
SP.akun=()=>usersTab();
/* Katalog Surat */
const suratRows=()=>{const q=(S.sq||'').toLowerCase().replace(/[^a-z0-9]/g,''),j=+S.sj||0;const r=SUR.map((x,i)=>({n:i+1,x,a:AY[i],j:juzOf(i+1)})).filter(s=>(!j||juzS(j).includes(s.n))&&(!q||s.x.toLowerCase().replace(/[^a-z0-9]/g,'').includes(q)||String(s.n)==q));return r.map(s=>`<tr><td>${s.n}</td><td><b>${esc(s.x)}</b></td><td>${s.a}</td><td>Juz ${j||s.j}</td></tr>`).join('')||'<tr><td colspan="4" class="mut">Surat tidak ditemukan</td></tr>'};
const drawSurat=()=>{$('#srt').innerHTML=suratRows()};
SP.surat=()=>`<div class="card"><div class="ch"><div><h3>Katalog surat</h3><p class="sub2" style="margin:0">114 surat beserta jumlah ayatnya, dipakai di Input Penilaian dan Jurnal Harian.</p></div><label>Juz awal di Input Penilaian<select onchange="S.juz=0;putSet({juzAwal:this.value})">${[...Array(30)].map((_,k)=>`<option value="${k+1}" ${k+1==(+S.set.juzAwal||30)?'selected':''}>Juz ${k+1}</option>`).join('')}</select></label></div><div class="fb"><input class="srch" placeholder="Cari nama atau nomor surat…" value="${esc(S.sq||'')}" oninput="S.sq=this.value;drawSurat()"><select onchange="S.sj=this.value;drawSurat()"><option value="">Semua juz</option>${[...Array(30)].map((_,k)=>`<option value="${k+1}" ${S.sj==k+1?'selected':''}>Juz ${k+1}</option>`).join('')}</select></div><div class="tw"><table><thead><tr><th>NO</th><th>SURAT</th><th>AYAT</th><th>JUZ</th></tr></thead><tbody id="srt">${suratRows()}</tbody></table></div></div>`;
/* WhatsApp */
