SP.wa=()=>{const t=S.set.waTemplate||WA_DEF,s=S.santri[0];return`<div class="sg"><div class="card"><h3>Templat pesan ke wali</h3><p class="sub2">Kode yang bisa dipakai: {wali} {nama} {kelas} {periode} {tpq} {hafalan} {rata} {tajwid} {catatan}</p><textarea id="f_wat" rows="13" oninput="waPrev()">${esc(t)}</textarea><div class="acts"><button class="btn ghost" onclick="$('#f_wat').value=WA_DEF;waPrev()">Kembalikan bawaan</button><button class="btn" onclick="putSet({waTemplate:val('wat')},'Templat tersimpan')">Simpan</button></div></div><div class="card"><h3>Pratinjau</h3><p class="sub2">${s?'Contoh untuk '+esc(s.nama):'Tambahkan santri untuk melihat contoh'}</p><div class="wap" id="wap">${esc(s?waMsg(s.id,t):t)}</div></div></div>`};
/* Backup & Data */
const BK=['Santri','Nilai','Rapor','Jurnal'];
SP.data=()=>`<div class="grid g2"><div class="card"><h3>Backup &amp; pulihkan</h3><p class="sub2">Berisi santri, nilai, rapor, jurnal, dan pengaturan. Akun pengguna tidak ikut. Saat dipulihkan, data digabung: yang sama ditimpa, yang lain tetap ada.</p><div class="acts"><button class="btn ghost" onclick="$('#rsf').click()">⬆ Pulihkan dari file</button><button class="btn" onclick="backup()">⬇ Unduh backup</button><input id="rsf" type="file" accept=".json,application/json" hidden onchange="restore(this)"></div></div>
<div class="card"><h3>Koneksi database</h3><p class="sub2">${API_URL?'Terhubung ke Google Spreadsheet via Apps Script.':'Mode demo aktif: data hanya tersimpan di browser ini. Isi API_URL di app.js dengan URL Web App Apps Script untuk memakai Spreadsheet.'}</p>${API_URL?'':'<div class="acts"><button class="btn red" onclick="hapusDemo()">Hapus Demo</button><button class="btn ghost" onclick="dataDemo()">Data Demo</button></div>'}</div></div>`;
async function backup(){try{const d=await api('all'),o={app:'tpq',dibuat:new Date().toISOString(),Settings:d.Settings};BK.forEach(k=>o[k]=d[k]||[]);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(o)],{type:'application/json'}));a.download=`backup-tpq-${ltoday()}.json`;a.click();toast('Backup diunduh')}catch(e){toast(e.message,1)}}
async function restore(el){const f=el.files[0];if(!f)return;el.value='';try{let o;try{o=JSON.parse(await f.text())}catch(e){}
if(!o||o.app!='tpq')throw Error('Ini bukan file backup aplikasi TPQ');if(!confirm('Pulihkan data dari '+f.name+'? Data dengan ID yang sama akan ditimpa.'))return;
const items=BK.flatMap(k=>(o[k]||[]).filter(x=>x&&x.id).map(obj=>({sheet:k,obj})));toast('Memulihkan data…');
for(let i=0;i<items.length;i+=50)await api('saveMany',{items:items.slice(i,i+50)});
await api('saveSettings',{map:o.Settings||{}});await load();usePer();render();toast('Data dipulihkan')}catch(e){toast(e.message,1)}}
S.sel=new Set();let LV=[];
const fd=t=>new Date(t).toLocaleString('id-ID',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
function paperHtml(id){const s=S.santri.find(x=>x.id==id),r=getR(id),H=r.hafalan,c=r.cat,x=ts(r),g=c.guru||s.guru||'';
return`<div class="paper">${kopHtml(S.set)}<table class="pi"><table class="pi"><tr><td>Nama</td><td>: <b>${esc(s.nama)}</b></td><td>Kelas</td><td>: ${esc(s.kelas)}</td></tr><tr><td>NIS / NISN</td><td>: ${esc(s.nis)} / ${esc(s.nisn)}</td><td>Guru halaqah</td><td>: ${esc(g)}</td></tr></table>
<h4>A. Hafalan</h4><table class="pt2 tA"><tr><th>No</th><th>Surat</th><th>Ayat</th><th>Nilai</th><th>Predikat</th><th>Makharijul huruf</th><th>Tajwid</th></tr>${H.map((h,i)=>`<tr><td>${i+1}</td><td>${SUR[h.sur-1]}${h.from>1||h.to<AY[h.sur-1]?` (${h.from}–${h.to})`:''}</td><td>${h.ayat}</td><td>${pc(h)||'-'}</td><td>${HP(h)[0]}</td><td>${esc(h.mk||'-')}</td><td>${esc(h.tj||'-')}</td></tr>`).join('')||'<tr><td colspan="7">Belum ada data hafalan</td></tr>'}</table>
<h4>B. Hasil ujian tajwid</h4><table class="pt2"><tr><th>Materi tajwid</th><th style="width:90px">Skor</th><th style="width:150px">Kategori</th></tr><tr><td>${esc(r.tajwid.materi||'-')}</td><td class="c"><b>${x??'-'}</b></td><td class="c">${tcat(x)[0]}</td></tr></table>
<h4>C. Catatan guru</h4><table class="pt2"><tr><th style="width:150px">Jenis catatan</th><th>Isi catatan</th></tr><tr><td><b>Catatan tahfizh</b></td><td class="tl">${esc(c.tahfiz||'-')}</td></tr><tr><td><b>Catatan tajwid</b></td><td class="tl">${esc(c.tjn||'-')}</td></tr></table>
${jrekap(id)}${tglRapor()}<div class="sign"><div><small>Guru Halaqah</small><span>${esc(g)||'&nbsp;'}</span></div><div><small>Wali Santri</small><span>${esc(s.wali)||'&nbsp;'}</span></div><div><small>${esc(S.set.jabatan||'Kepala TPQ')}</small><span>${esc(S.set.ketua)||'&nbsp;'}</span></div></div></div>`}
function kopHtml(o){const lg=o.logo&&o.kopLogo!='0'?`<img class="lm" src="${esc(o.logo)}" alt="Logo">`:o.kopLogo=='0'?'':'<div class="lm">ح</div>';
return`<div class="ph">${lg}<div>${o.kopYayasan?`<small class="ky">${esc(o.kopYayasan)}</small>`:''}<h2>${esc(o.namaTpq)}</h2>${o.kopAlamat?`<small>${esc(o.kopAlamat)}</small>`:''}${o.kopKontak?`<small>${esc(o.kopKontak)}</small>`:''}<b>${esc(o.kopJudul||'PENILAIAN SUMATIF AKHIR SEMESTER')}</b><br><span class="mut">${perLabel(S.per)} · Tahun Pelajaran ${esc(yr())}</span></div></div>`}
function tglRapor(){const t=String(S.set.tglRapor||'').slice(0,10),k=S.set.kota||'';if(!t&&!k)return'';return`<div class="sgd">${esc(k)}${k&&t?', ':''}${t?new Date(t+'T00:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'}):''}</div>`}
const MACT='<div class="acts noprint"><button class="btn ghost" onclick="closeM()">Tutup</button><button class="btn ghost" onclick="printM()">Cetak</button><button class="btn" id="bpdf" onclick="savePdf()">Simpan PDF</button></div>';
function printM(){document.body.classList.add('pm');print();document.body.classList.remove('pm')}
function loadPdfLib(){return window.html2pdf?Promise.resolve():new Promise((ok,no)=>{const e=document.createElement('script');e.src='https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js';e.onload=ok;e.onerror=()=>no(new Error('Pustaka PDF gagal dimuat. Periksa koneksi internet atau gunakan tombol Cetak.'));document.head.appendChild(e)})}
async function savePdf(){const ids=S.rp||[];if(!ids.length)return;const b=$('#bpdf'),t=b.textContent;b.disabled=true;b.textContent='Membuat PDF…';
try{await loadPdfLib();const w=document.createElement('div');w.className='pdfmode';w.style.width='718px';w.innerHTML=ids.map(paperHtml).join('');
const sn=ids.length==1?S.santri.find(x=>x.id==ids[0]):null,nm=sn?'Rapor_'+sn.nama.replace(/[^\w]+/g,'_'):'Rapor_'+ids.length+'_santri';
await html2pdf().set({margin:[10,10,10,10],filename:nm+'.pdf',image:{type:'jpeg',quality:.98},html2canvas:{scale:2,useCORS:true,backgroundColor:'#ffffff',scrollX:0,scrollY:0},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'},pagebreak:{mode:['css','legacy'],avoid:['tr','h4','.sign']}}).from(w).save()}
catch(e){toast(e.message||'Gagal membuat PDF',1)}
b.disabled=false;b.textContent=t}
function rapor(id){S.rp=[id];modal(paperHtml(id)+MACT)}
function cetak(ids){if(!ids.length)return;S.rp=ids;modal(ids.map(paperHtml).join('')+MACT)}
V.laporan=()=>{const w=S.user.role=='wali';return`<div class="top lp-top"><div><h1 class="pt">Rapor PDF</h1><p class="sub" style="margin:0;max-width:640px;font-size:16px;line-height:1.6">PENILAIAN SUMATIF AKHIR SEMESTER · ${perRange(S.per)}. Pratinjau lalu cetak atau simpan sebagai PDF (A4), satu per satu atau sekaligus.</p></div><div class="ta">${w?'':`<button class="btn ghost" id="bwa" onclick="sendSel()" disabled>${ic('wa',18)}Kirim WA terpilih</button>`}<button class="btn" id="bpr" onclick="cetak([...S.sel])" disabled>${ic('print',18)}<span>Cetak terpilih ( 0 )</span></button></div></div><div class="card"><div class="fb"><div class="sbox">${ic('search',18)}<input class="srch" placeholder="Cari siswi…" value="${esc(S.q)}" oninput="S.q=this.value;drawLap()"></div><select onchange="S.fk=this.value;drawLap()"><option value="">Semua kelas</option>${kelasL().map(k=>`<option ${S.fk==k?'selected':''}>${esc(k)}</option>`).join('')}</select><select onchange="S.fs=this.value;drawLap()"><option value="">Semua status</option>${['Selesai','Proses','Belum'].map(x=>`<option ${S.fs==x?'selected':''}>${x}</option>`).join('')}</select></div><label class="selall"><input type="checkbox" onchange="selAll(this.checked)"> Pilih semua</label><div id="lp"></div></div>`};
function cnt(){const n=S.sel.size,b=$('#bpr');if(!b)return;b.innerHTML=ic('print',18)+'<span>Cetak terpilih ( '+n+' )</span>';b.disabled=!n;if($('#bwa'))$('#bwa').disabled=!n}
function drawLap(){const w=S.user.role=='wali';LV=flt().map(s=>{const r=getR(s.id);return{s,r,p:pgR(r)}}).filter(x=>!S.fs||(S.fs=='Belum'?x.p==0:S.fs=='Proses'?x.p>0&&x.p<100:x.p==100));
$('#lp').innerHTML=!LV.length?'<p class="mut">Tidak ada siswi.</p>':`<div class="tw"><table class="tbl lap"><tr><th style="width:44px"><input type="checkbox" onchange="selAll(this.checked)" ${LV.every(x=>S.sel.has(x.s.id))?'checked':''}></th><th>SISWI</th><th>KELAS</th><th>DIPERBARUI</th><th>STATUS</th>${w?'':'<th>WHATSAPP WALI</th>'}<th style="text-align:right">AKSI</th></tr>${LV.map(({s,r,p})=>{const t=p==100?['Selesai','g']:p>0?['Proses','y']:['Belum','na'];return`<tr><td><input type="checkbox" ${S.sel.has(s.id)?'checked':''} onchange="selOne('${s.id}',this.checked)"></td><td><div class="nm" style="cursor:default"><span class="ai">${ini(s.nama)}</span><div><b>${esc(s.nama)}</b><br><small class="mut">NIS ${esc(s.nis)}</small></div></div></td><td><span class="pl">${esc(s.kelas)}</span></td><td class="mut tdt">${r.ts?fd(r.ts):'-'}</td><td><span class="st ${t[1]}">${t[0]}</span></td>${w?'':`<td class="twa">${r.wa?`<span class="st g">${ic('check',14)}${fd(r.wa)}</span>`:`<span class="mono mut">${esc(s.wa)||'-'}</span>`}</td>`}<td><div class="ac"><button class="btn sm ghost pv" onclick="rapor('${s.id}')">${ic('eye',16)}Pratinjau</button><button class="btn sm ghost" onclick="cetak(['${s.id}'])">${ic('print',16)}Cetak</button>${w?'':`<button class="btn sm wa" onclick="sendWA('${s.id}')">${ic('wa',16)}WA</button>`}</div></td></tr>`}).join('')}</table></div>`;cnt()}
function selAll(v){LV.forEach(x=>v?S.sel.add(x.s.id):S.sel.delete(x.s.id));drawLap()}
function selOne(id,v){v?S.sel.add(id):S.sel.delete(id);cnt()}
const WA_DEF=`Assalamu'alaikum Bapak/Ibu {wali},

Berikut ringkasan rapor halaqah Ananda {nama} ({kelas}) periode {periode} di {tpq}:
• Hafalan: {hafalan} surat, rata-rata {rata}
• Tajwid: {tajwid}

Catatan: {catatan}

Barakallahu fik.`;
const fillT=(t,m)=>t.replace(/\{(\w+)\}/g,(x,k)=>k in m?m[k]:x);
function waMsg(id,tp){const s=S.santri.find(x=>x.id==id),r=getR(id),ps=r.hafalan.map(pct).filter(v=>v!=null),a=ps.length?avg(ps):null,x=ts(r);return fillT(tp||S.set.waTemplate||WA_DEF,{wali:s.wali||'Wali Santri',nama:s.nama,kelas:s.kelas,periode:perLabel(S.per),tpq:S.set.namaTpq,hafalan:r.hafalan.length,rata:a==null?'-':f1(a)+'%',tajwid:x==null?'-':x+' ('+tcat(x)[0]+')',catatan:r.cat.tahfiz||'-'})}
function sendWA(id){const s=S.santri.find(x=>x.id==id);let n=String(s.wa||'').replace(/\D/g,'');if(n.startsWith('0'))n='62'+n.slice(1);if(!n)return toast('Nomor WhatsApp wali belum diisi (menu Santri > edit)',1);
window.open('https://wa.me/'+n+'?text='+encodeURIComponent(waMsg(id)),'_blank');
const r=getR(id);r.wa=Date.now();api('save',{sheet:'Rapor',obj:{id:id+'_'+pk(),santriId:id,periode:pk(),data:JSON.stringify(r)}}).then(load).then(drawLap).catch(e=>toast(e.message,1))}
function sendSel(){const ids=[...S.sel];toast('Jika hanya satu jendela terbuka, izinkan pop-up di browser');ids.forEach(sendWA)}
/* ===== JURNAL HARIAN ===== */
const HCL={Hadir:'g',Izin:'y',Sakit:'y',Alpa:'r'},MCL={'Lancar':'g','Cukup':'y','Perlu diulang':'r'};
const jid=(s,d)=>`jr_${s}_${d}`,jlist=id=>(S.jurnal||[]).filter(x=>x.santriId==id).sort((a,b)=>b.tanggal.localeCompare(a.tanggal));
const fmtD=d=>new Date(d+'T00:00:00').toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),fmtS=d=>new Date(d+'T00:00:00').toLocaleDateString('id-ID',{weekday:'short',day:'numeric',month:'short'});
const jsur=e=>e&&e.surat?SUR[e.surat-1]+(+e.dari==1&&+e.sampai==AY[e.surat-1]?'':` (${e.dari}–${e.sampai})`):'-';
function perDates(k){if(!k)return['0000-00-00','9999-99-99'];const y=+k.slice(0,4),m=+k.slice(5,7),n=m%3==1?3:1;return[k+'-01',new Date(Date.UTC(y,m-1+n,0)).toISOString().slice(0,10)]}
function jrekap(id){const[a,b]=perDates(S.per),l=jlist(id).filter(x=>x.tanggal>=a&&x.tanggal<=b);if(!l.length)return'';const c=k=>l.filter(x=>x.hadir==k).length,j=k=>l.filter(x=>x.hadir=='Hadir'&&x.jenis==k).length;return`<h4>D. Kehadiran &amp; setoran harian</h4><table class="pt2 pd"><tr><th rowspan="2">Pertemuan tercatat</th><th colspan="4">Kehadiran</th><th colspan="3">Setoran (kali)</th></tr><tr><th>Hadir</th><th>Izin</th><th>Sakit</th><th>Alpa</th><th>Ziyadah</th><th>Murajaah</th><th>Tahsin</th></tr><tr class="c"><td class="c"><b>${l.length}</b></td><td class="c">${c('Hadir')}</td><td class="c">${c('Izin')}</td><td class="c">${c('Sakit')}</td><td class="c">${c('Alpa')}</td><td class="c">${j('Ziyadah')}</td><td class="c">${j('Murajaah')}</td><td class="c">${j('Tahsin')}</td></tr></table>`}
const jrow=x=>`<tr><td>${fmtS(x.tanggal)}</td><td><span class="st ${HCL[x.hadir]||''}">${esc(x.hadir)}</span></td><td>${x.hadir=='Hadir'?(x.jenis?`<b>${esc(x.jenis)}</b> · `:'')+esc(jsur(x)):'-'}</td><td>${x.mutu?`<span class="st ${MCL[x.mutu]||''}">${esc(x.mutu)}</span>`:'-'}</td><td class="mut">${esc(x.catatan)||'-'}</td></tr>`;
const jcount=(l,k)=>l.filter(x=>x.hadir==k).length,jchips=l=>`<div class="jsum">${['Hadir','Izin','Sakit','Alpa'].map(k=>`<span class="st ${HCL[k]}">${k} ${jcount(l,k)}</span>`).join('')}</div>`;
function jWali(){return`<div class="top"><div><h1 class="pt">Jurnal Harian</h1><p class="sub" style="margin:0">Kehadiran dan setoran hafalan harian Ananda, sesuai catatan guru.</p></div></div>${S.santri.map(s=>{const l=jlist(s.id),m=l.filter(x=>x.tanggal>=addD(ltoday(),-29));return`<div class="card" style="margin-bottom:16px"><div class="hero"><div class="av">${ini(s.nama)}</div><div><h3 style="margin:0">${esc(s.nama)}</h3><span class="mut">${esc(s.kelas)} · 30 hari terakhir</span></div></div>${jchips(m)}<div class="tw"><table class="tbl"><tr><th>TANGGAL</th><th>KEHADIRAN</th><th>SETORAN</th><th>KELANCARAN</th><th>CATATAN</th></tr>${l.slice(0,14).map(jrow).join('')||'<tr><td colspan="5" class="mut">Belum ada catatan jurnal.</td></tr>'}</table></div></div>`}).join('')||'<div class="card">Belum ada santri yang terhubung ke akun Anda.</div>'}`}
V.jurnal=()=>{if(S.user.role=='wali')return jWali();return`<div class="top"><div><h1 class="pt">Jurnal Harian</h1><p class="sub" style="margin:0;max-width:600px"><span id="jdl"></span>. Catat kehadiran dan setoran hafalan tiap hari; rekapnya ikut tampil di rapor.</p></div><div class="ta jdate"><button class="ib" onclick="jgo(-1)">‹</button><input type="date" id="jd" value="${S.jd}" max="${ltoday()}" onchange="jgo(this.value)"><button class="ib" onclick="jgo(1)">›</button><button class="btn ghost" onclick="jgo(0)">Hari ini</button></div></div><div class="card"><div class="fb"><div class="sbox">${ic('search',18)}<input class="srch" placeholder="Cari santri…" value="${esc(S.q)}" oninput="S.q=this.value;drawJ()"></div><select onchange="S.fk=this.value;drawJ()"><option value="">Semua kelas</option>${kelasL().map(k=>`<option ${S.fk==k?'selected':''}>${esc(k)}</option>`).join('')}</select></div><div id="jl"></div></div>`};
function jgo(n){const t=ltoday();let d=typeof n=='string'?n:n==0?t:addD(S.jd,n);if(!d||d>t)d=t;S.jd=d;$('#jd').value=d;drawJ()}
function drawJ(){if(S.user.role=='wali'||!$('#jl'))return;$('#jdl').textContent=fmtD(S.jd);const ix={};(S.jurnal||[]).filter(x=>x.tanggal==S.jd).forEach(x=>ix[x.santriId]=x);const l=flt(),c=k=>l.filter(s=>ix[s.id]&&ix[s.id].hadir==k).length,done=l.filter(s=>ix[s.id]).length;
$('#jl').innerHTML=`<div class="jsum">${['Hadir','Izin','Sakit','Alpa'].map(k=>`<span class="st ${HCL[k]}">${k} ${c(k)}</span>`).join('')}<span class="st">Belum dicatat ${l.length-done}</span><button class="btn ghost sm" onclick="jall()">✓ Tandai semua hadir</button></div>`+(!l.length?'<p class="mut">Tidak ada santri.</p>':`<div class="tw"><table class="tbl jt"><tr><th>SANTRI</th><th>KELAS</th><th>KEHADIRAN</th><th>SETORAN</th><th>KELANCARAN</th><th style="text-align:right">AKSI</th></tr>${l.map(s=>{const e=ix[s.id],hd=e&&e.hadir=='Hadir';return`<tr><td><div class="nm" onclick="jhist('${s.id}')"><span class="ai">${ini(s.nama)}</span><b>${esc(s.nama)}</b></div></td><td><span class="pl">${esc(s.kelas)}</span></td><td><div class="jq">${[['Hadir','H'],['Izin','I'],['Sakit','S'],['Alpa','A']].map(([k,t])=>`<b class="h${t} ${e&&e.hadir==k?'on':''}" title="${k}" onclick="jq('${s.id}','${k}')">${t}</b>`).join('')}</div></td><td class="jst">${hd?(e.jenis?`<b>${esc(e.jenis)}</b> · `:'')+esc(jsur(e)):'-'}</td><td>${hd&&e.mutu?`<span class="st ${MCL[e.mutu]||''}">${esc(e.mutu)}</span>`:''}</td><td><div class="ac"><button class="btn sm ghost pv" onclick="jform('${s.id}')">${ic('nilai',16)}${hd?'Ubah setoran':'Isi setoran'}</button></div></td></tr>`}).join('')}</table></div>`)}
async function jq(id,h){const e=(S.jurnal||[]).find(x=>x.santriId==id&&x.tanggal==S.jd);if(e&&e.hadir==h)return;const o={id:jid(id,S.jd),tanggal:S.jd,santriId:id,hadir:h,guru:S.user.nama};if(h!='Hadir'){o.jenis='';o.surat='';o.dari='';o.sampai='';o.mutu=''}
try{await api('save',{sheet:'Jurnal',obj:o});await load();drawJ()}catch(x){toast(x.message,1)}}
async function jall(){const ix=new Set((S.jurnal||[]).filter(x=>x.tanggal==S.jd).map(x=>x.santriId)),items=flt().filter(s=>!ix.has(s.id)).map(s=>({sheet:'Jurnal',obj:{id:jid(s.id,S.jd),tanggal:S.jd,santriId:s.id,hadir:'Hadir',guru:S.user.nama}}));if(!items.length)return toast('Semua santri sudah dicatat');
try{await api('saveMany',{items});await load();drawJ();toast(items.length+' santri ditandai hadir')}catch(x){toast(x.message,1)}}
let JF={};
function jsetv(k,v){JF[k]=v;document.querySelectorAll('#j_'+k+' .chip').forEach(c=>c.classList.toggle('on',c.dataset.v==v));if(k=='h')$('#jdet').style.display=v=='Hadir'?'block':'none'}
function jsurCh(){const n=+$('#f_sur').value;$('#f_dari').value=n?1:'';$('#f_sampai').value=n?AY[n-1]:''}
function jform(id){const d=S.jd,s=S.santri.find(x=>x.id==id),e=(S.jurnal||[]).find(x=>x.santriId==id&&x.tanggal==d)||{};JF={id,d,h:e.hadir||'Hadir',mu:e.mutu||'Lancar',j:e.jenis||'Ziyadah'};
const ch=(k,a)=>`<div class="chips" id="j_${k}">${a.map(v=>`<span class="chip ${JF[k]==v?'on':''}" data-v="${v}" onclick="jsetv('${k}','${v}')">${v}</span>`).join('')}</div>`;
modal(`<div class="jform"><h3>Jurnal · ${esc(s.nama)}</h3><p class="mut" style="margin-bottom:14px">${fmtD(d)}</p><label>Kehadiran</label>${ch('h',['Hadir','Izin','Sakit','Alpa'])}<div id="jdet" style="display:${JF.h=='Hadir'?'block':'none'};margin-top:16px"><label>Jenis setoran</label>${ch('j',['Ziyadah','Murajaah','Tahsin'])}<div class="fg jf" style="margin-top:14px"><label class="full">Surat<select id="f_sur" onchange="jsurCh()"><option value="">- tidak ada setoran -</option>${SUR.map((x,i)=>`<option value="${i+1}" ${e.surat==i+1?'selected':''}>${i+1}. ${x} (${AY[i]} ayat)</option>`).join('')}</select></label>${inp('dari','Dari ayat',e.dari,'number')}${inp('sampai','Sampai ayat',e.sampai,'number')}</div><label style="margin-top:16px">Kelancaran</label>${ch('mu',['Lancar','Cukup','Perlu diulang'])}</div><label style="margin-top:14px">Catatan<textarea id="f_cat" rows="3">${esc(e.catatan||'')}</textarea></label><div class="acts"><button class="btn ghost" onclick="closeM()">Batal</button>${e.id?`<button class="btn red" onclick="rm('Jurnal','${e.id}')">Hapus</button>`:''}<button class="btn" onclick="jsave()">Simpan</button></div></div>`)}
function jsave(){const J=JF,hd=J.h=='Hadir',sn=hd?$('#f_sur').value:'';let dr='',sm='';if(sn){dr=+val('dari')||1;sm=+val('sampai')||AY[sn-1];if(dr<1||sm>AY[sn-1]||dr>sm)return toast(`Rentang ayat tidak valid (1–${AY[sn-1]})`,1)}
sv('Jurnal',{id:jid(J.id,J.d),tanggal:J.d,santriId:J.id,hadir:J.h,jenis:sn?J.j:'',surat:sn?+sn:'',dari:dr,sampai:sm,mutu:sn?J.mu:'',catatan:$('#f_cat').value.trim(),guru:S.user.nama},'Jurnal tersimpan')}
function jhist(id){const s=S.santri.find(x=>x.id==id),l=jlist(id),m=l.filter(x=>x.tanggal>=addD(ltoday(),-29));modal(`<div class="hero"><div class="av">${ini(s.nama)}</div><div><h3 style="margin:0">${esc(s.nama)}</h3><span class="mut">${esc(s.kelas)} · 30 hari terakhir</span></div></div>${jchips(m)}<div class="tw"><table class="tbl"><tr><th>TANGGAL</th><th>KEHADIRAN</th><th>SETORAN</th><th>KELANCARAN</th><th>CATATAN</th></tr>${l.slice(0,14).map(jrow).join('')||'<tr><td colspan="5" class="mut">Belum ada catatan jurnal.</td></tr>'}</table></div><div class="acts"><button class="btn ghost" onclick="closeM()">Tutup</button><button class="btn" onclick="closeM();jform('${id}')">Isi jurnal ${fmtS(S.jd)}</button></div>`)}
/* ===== INIT ===== */
(async()=>{const s=sessionStorage.getItem('tpq_s');if(s){try{const r=JSON.parse(s);S.token=r.token;S.user=r.user;await load();usePer();return render()}catch(e){sessionStorage.clear()}}loginView()})();

function saveDb(d){localStorage.setItem('tpq_db2',JSON.stringify(d));S.sel=new Set();S.cur=null;return load().then(render)}
function dataDemo(){if(!confirm('Buat data demo dengan kegiatan 7 hari terakhir? Data demo lama diganti baru. Data asli Anda tidak terhapus.'))return;const d=db(),x=demoData();d.Santri=[...d.Santri.filter(v=>!isDm(v)),...x.Santri];d.Nilai=[...d.Nilai.filter(v=>!isDm(v)),...x.Nilai];d.Rapor=[...d.Rapor.filter(v=>!isDm(v)),...x.Rapor];d.Jurnal=[...(d.Jurnal||[]).filter(v=>!isDm(v)),...x.Jurnal];d.Users.forEach(u=>{if(u.role=='wali'&&String(u.santriId||'').split(',').every(dmId))u.santriId='demo-1,demo-2'});saveDb(d).then(()=>toast('Data demo dibuat')).catch(e=>toast(e.message,1))}
function hapusDemo(){const d=db();if(!d.Santri.some(isDm)&&!d.Nilai.some(isDm)&&!d.Rapor.some(isDm)&&!(d.Jurnal||[]).some(isDm))return toast('Tidak ada data demo');if(!confirm('Hapus data demo saja (santri, nilai, rapor contoh)? Data asli yang Anda input tidak ikut terhapus.'))return;d.Santri=d.Santri.filter(v=>!isDm(v));d.Nilai=d.Nilai.filter(v=>!isDm(v));d.Rapor=d.Rapor.filter(v=>!isDm(v));d.Jurnal=(d.Jurnal||[]).filter(v=>!isDm(v));saveDb(d).then(()=>toast('Data demo dihapus')).catch(e=>toast(e.message,1))}
